  body:`${animation}let step=0;const fields=[root.querySelector('[data-hardware]'),root.querySelector('[data-network]'),root.querySelector('[data-replicas]')];const render=()=>{fields.forEach((field,i)=>{field.parentElement.hidden=i!==step;});const replicas=Math.min(10,Math.max(1,Number(fields[2].value)||1));root.querySelector('[data-total]').textContent='$'+((Number(fields[0].value)+Number(fields[1].value))*replicas)+' / mes';root.querySelector('[data-progress]').style.setProperty('--progress',((step+1)/3*100)+'%');root.querySelector('[role=progressbar]').setAttribute('aria-valuenow',String(step+1));root.querySelector('[data-prev]').disabled=step===0;root.querySelector('[data-next]').disabled=step===2;root.querySelector('[role=status]').textContent='Paso '+(step+1)+' de 3';run(root.querySelector('[data-total]'),{scale:[.9,1],duration:300,ease:'outCubic'});};fields.forEach(field=>field.addEventListener('input',render,{signal}));root.querySelector('[data-prev]').addEventListener('click',()=>{step=Math.max(0,step-1);render();},{signal});root.querySelector('[data-next]').addEventListener('click',()=>{step=Math.min(2,step+1);render();},{signal});root.querySelector('[data-reset]').addEventListener('click',()=>{step=0;fields[0].value='20';fields[1].value='10';fields[2].value='1';render();},{signal});render();`
